#!/usr/bin/env node
// Build the Scalene UI into a single self-contained script.
//
//   node build.mjs            -> dist/scalene-gui-bundle.js (+ post-build checks)
//   node build.mjs --check    -> type-check only
//
// Steps: (1) inline src/styles/*.css into src/generated/styles.ts,
// (2) compile src/ with tsc (CommonJS, into build/), (3) wrap every
// compiled module in a tiny require() registry and emit one IIFE,
// (4) verify the integration contract (DESIGN.md §7.5): required literals,
// forbidden strings, the TS entry's text shape, the template, and the size
// budget (§6.1). A failed check exits 1 (the bundle is still written so it
// can be inspected). No npm dependencies: needs only Node and a TypeScript
// compiler (`tsc` on PATH or node_modules/.bin/tsc).
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";
import { cssClassCollisions } from "./tools/css-ownership.mjs";

const root = path.dirname(fileURLToPath(import.meta.url));
const src = path.join(root, "src");
const out = path.join(root, "build");
const dist = path.join(root, "dist");
const checkOnly = process.argv.includes("--check");

// 1. CSS -> TS string module, files concatenated in name order. Comments and
// redundant whitespace are dropped (the size budget counts the shipped text).
const styleDir = path.join(src, "styles");
const css = fs
  .readdirSync(styleDir)
  .filter((f) => f.endsWith(".css"))
  .sort()
  .map((f) => `/* ${f} */\n` + compactCss(fs.readFileSync(path.join(styleDir, f), "utf8")))
  .join("\n");

/**
 * Strip comments, collapse whitespace, drop spaces around braces and semicolons, and drop the
 * space after ":" and "," outside quoted strings (a colon followed by a space only occurs in
 * declarations and media features; a comma never needs the space). Spaces around + - * / are
 * kept because calc() needs them.
 */
function compactCss(text) {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\s+/g, " ")
    .replace(/\s*([{};])\s*/g, "$1")
    .replace(/;}/g, "}")
    .replace(/("[^"]*"|'[^']*')|([:,]) /g, (m, quoted, punct) => quoted ?? punct)
    .trim();
}
fs.mkdirSync(path.join(src, "generated"), { recursive: true });
fs.writeFileSync(
  path.join(src, "generated", "styles.ts"),
  "// Generated by build.mjs from src/styles/*.css. Do not edit.\n" +
    `export const CSS = ${JSON.stringify(css)};\n`,
);

// 2. Type-check / compile.
const localTsc = path.join(root, "node_modules", ".bin", "tsc");
const tsc = fs.existsSync(localTsc) ? localTsc : "tsc";
const ts = loadTypeScript();
fs.rmSync(out, { recursive: true, force: true });
try {
  execFileSync(tsc, ["-p", root, ...(checkOnly ? ["--noEmit"] : [])], {
    stdio: "inherit",
  });
} catch {
  process.exit(1);
}
if (checkOnly) process.exit(0);

// 3. Bundle: module id = path relative to build/ without extension.
const modules = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".js")) modules.push(p);
  }
})(out);
modules.sort();
const id = (p) => path.relative(out, p).replace(/\\/g, "/").replace(/\.js$/, "");
let body = "";
for (const p of modules) {
  const code = trimCommonJs(fs.readFileSync(p, "utf8").replace(/^\/\/# sourceMappingURL=.*$/m, ""));
  body += `${JSON.stringify(id(p))}: function (require, module, exports) {\n${dedent(code)}\n},\n`;
}
const bundle = `/* Scalene UI bundle - generated by build.mjs. Do not edit. */
(function () {
"use strict";
var defs = {
${body}};
var cache = {};
function resolve(from, spec) {
  if (spec.charAt(0) !== ".") throw new Error("scalene-ui: external module " + spec);
  var parts = from.split("/"); parts.pop();
  spec.split("/").forEach(function (s) {
    if (s === "..") parts.pop(); else if (s !== ".") parts.push(s);
  });
  var name = parts.join("/").replace(/\\.js$/, "");
  return defs[name] ? name : name + "/index";
}
function load(name) {
  if (cache[name]) return cache[name].exports;
  var module = (cache[name] = { exports: {} });
  defs[name](function (spec) { return load(resolve(name, spec)); }, module, module.exports);
  return module.exports;
}
load("main");
})();
`;
fs.mkdirSync(dist, { recursive: true });
fs.writeFileSync(path.join(dist, "scalene-gui-bundle.js"), bundle);
const bundleBytes = Buffer.byteLength(bundle, "utf8");
console.log(`dist/scalene-gui-bundle.js  ${(bundleBytes / 1024).toFixed(1)} KiB, ${modules.length} modules`);

/**
 * Drop CommonJS boilerplate the tiny registry below never needs (§6.1 size budget; the code
 * stays unminified and readable): each module's "use strict" (the bundle's IIFE already has the
 * directive, which covers every nested module function), the `__esModule` marker (no interop helpers read it), the
 * `exports.a = exports.b = void 0;` pre-declarations (an import read before its assignment is
 * `undefined` either way) and tsc's `(0, mod_1.fn)(…)` call wrapper, which only forces
 * `this === undefined` (no module-level function uses `this`). Saves ~20 KiB raw.
 */
function trimCommonJs(code) {
  return code
    .replace(/^\s*"use strict";\n/m, "")
    .replace(/^\s*Object\.defineProperty\(exports, "__esModule", \{ value: true \}\);\n/gm, "")
    .replace(/^\s*exports\.[\w$]+ = (?:exports\.[\w$]+ = )*void 0;\n/gm, "")
    .replace(/\(0, ([a-z_$][\w$]*_\d+\.[\w$]+)\)\(/g, "$1(");
}

/**
 * The TypeScript compiler module that belongs to the `tsc` in use (local install, else the
 * one on PATH), or null. Used only to re-indent the emitted JavaScript safely.
 */
function loadTypeScript() {
  const candidates = [path.join(root, "node_modules", "typescript", "lib", "typescript.js")];
  for (const dir of (process.env.PATH ?? "").split(path.delimiter)) {
    const bin = path.join(dir, "tsc");
    if (!fs.existsSync(bin)) continue;
    candidates.push(path.join(path.dirname(fs.realpathSync(bin)), "..", "lib", "typescript.js"));
  }
  const req = createRequire(import.meta.url);
  for (const c of candidates) {
    try {
      if (fs.existsSync(c)) return req(c);
    } catch {
      // Not loadable: try the next candidate.
    }
  }
  return null;
}

/**
 * Drop the leading indentation of one compiled module. Names and line breaks are kept, so
 * the bundle stays unminified and stack traces still point at readable lines, while saving
 * ~8.7 KiB gzipped against the §6.1 budget. Lines that start
 * inside a multi-line template or string literal keep their text: the literal ranges come
 * from the TypeScript parser. Without the compiler module the code is returned unchanged.
 */
function dedent(code) {
  if (!ts) return code;
  const sf = ts.createSourceFile("m.js", code, ts.ScriptTarget.ES2020, false, ts.ScriptKind.JS);
  const K = ts.SyntaxKind;
  const literalKinds = new Set([
    K.NoSubstitutionTemplateLiteral,
    K.TemplateHead,
    K.TemplateMiddle,
    K.TemplateTail,
    K.StringLiteral,
  ]);
  const keep = [];
  (function visit(node) {
    if (literalKinds.has(node.kind)) {
      const start = node.getStart(sf);
      if (code.slice(start, node.end).includes("\n")) keep.push([start, node.end]);
    }
    ts.forEachChild(node, visit);
  })(sf);
  const inLiteral = (pos) => keep.some(([a, b]) => pos > a && pos < b);
  let pos = 0;
  return code
    .split("\n")
    .map((line) => {
      const at = pos;
      pos += line.length + 1;
      return inLiteral(at) ? line : line.trimStart();
    })
    .join("\n");
}

// 4. Post-build checks (§7.5 upstream test contract, §6.1 budget).
const failures = verify(bundle, bundleBytes);
if (failures.length) {
  console.error(`\nbuild checks failed (${failures.length}):`);
  for (const f of failures) console.error(`  - ${f}`);
  process.exit(1);
}
console.log("build checks passed (literals, forbidden strings, TS entry shape, template, size budget)");

function verify(bundleText, bytes) {
  const out = [];
  // Upstream ships 1,426 KiB of page assets (445 KiB gzipped: Vega bundle, Bootstrap, jQuery, Prism);
  // this bundle replaces all of them, CSS included. Gzip is what a served page transfers.
  const BUDGET_KIB = 1000;
  const GZIP_BUDGET_KIB = 260;
  // Global names used in onclick handlers and real class names (§4.11.4, §4.12.2).
  for (const lit of [
    "toggleCombinedStacks",
    "toggleCombinedStacksTimeline",
    "toggleMemoryStacks",
    "timeline-axis",
    "timeline-gridlines",
    "memory-axis",
    "memory-gridlines",
  ]) {
    if (!bundleText.includes(lit)) out.push(`bundle is missing the literal ${JSON.stringify(lit)}`);
  }
  // The bundle is inlined into a <script> in standalone mode and must not leak test markers.
  const lower = bundleText.toLowerCase();
  for (const [needle, ci] of [
    ["</script", true],
    ["<!--", false],
    ["experimental", true],
    ["bg-warning text-dark", false],
    ["marker_native_symbol", false],
    ["user_inner_function", false],
  ]) {
    if ((ci ? lower : bundleText).includes(needle)) out.push(`bundle contains the forbidden string ${JSON.stringify(needle)}`);
  }
  if (bytes > BUDGET_KIB * 1024) {
    out.push(`bundle is ${(bytes / 1024).toFixed(1)} KiB, over the ${BUDGET_KIB} KiB budget`);
  }
  const gz = gzipSync(bundleText).length;
  if (gz > GZIP_BUDGET_KIB * 1024) {
    out.push(`bundle is ${(gz / 1024).toFixed(1)} KiB gzipped, over the ${GZIP_BUDGET_KIB} KiB budget`);
  }
  out.push(...verifyCssOwnership(styleDir));
  out.push(...verifyEntry(path.join(src, "scalene-gui.ts")));
  out.push(...verifyTemplate(path.join(root, "template", "index.html.template")));
  return out;
}

function verifyCssOwnership(dir) {
  const files = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".css"))
    .sort()
    .map((f) => [f, fs.readFileSync(path.join(dir, f), "utf8")]);
  return cssClassCollisions(files).map((c) => `CSS class collision between packages: ${c}`);
}

// Re-implements the text checks of upstream tests/test_combined_stacks_gui.py on our TS entry.
function verifyEntry(file) {
  if (!fs.existsSync(file)) return [`missing TS entry ${path.relative(root, file)}`];
  const text = fs.readFileSync(file, "utf8");
  const out = [];
  for (const sym of [
    "pickNiceTickInterval",
    "formatTimelineTickLabel",
    "renderTimelineAxis",
    "renderTimelineGridlines",
    "formatMemoryTickLabel",
    "renderMemoryAxis",
    "renderMemoryGridlines",
    "makeFileSourceLookup",
    "renderTimelineFrames",
    "renderTimelineContent",
  ]) {
    if (!text.includes(sym)) out.push(`scalene-gui.ts is missing ${sym}`);
  }
  const marker = "renderCombinedStacksTimeline";
  const start = text.indexOf(`export function ${marker}`);
  if (start === -1) return [...out, `scalene-gui.ts: "export function ${marker}" not found`];
  let end = text.indexOf("\nexport function ", start + marker.length + 10);
  if (end === -1) end = text.indexOf("\nfunction ", start + marker.length + 10);
  const body = end > start ? text.slice(start, end) : text.slice(start);
  if (!body.includes("makeFileSourceLookup")) out.push(`${marker} must construct makeFileSourceLookup`);
  if (!body.includes("renderTimelineContent")) out.push(`${marker} must call renderTimelineContent`);
  const cStart = text.indexOf("function renderTimelineContent");
  if (cStart === -1) return [...out, "scalene-gui.ts: renderTimelineContent definition not found"];
  const cEnd = text.indexOf("\nfunction ", cStart + 30);
  const cBody = cEnd > cStart ? text.slice(cStart, cEnd) : text.slice(cStart);
  if (!cBody.includes("sourceLookup")) out.push("renderTimelineContent must accept and pass sourceLookup");
  return out;
}

// The template contract of §7.1: variables, both modes, guarded + escaped profile, test selectors.
function verifyTemplate(file) {
  if (!fs.existsSync(file)) return [`missing template ${path.relative(root, file)}`];
  const text = fs.readFileSync(file, "utf8");
  const out = [];
  for (const needle of [
    // Empty/whitespace guard + '<' escaped so source text can never end the inline <script>.
    `const profile = {{ ((profile or '') | trim or '""') | replace('<', '\\\\u003c') }};`,
    "{{ scalene_version }}",
    "{{ scalene_date }}",
    "{{ gui_js }}",
    "{{ favicon_base64 }}",
    "{% if standalone %}",
    "{% if not standalone %}",
    'src="scalene-gui-bundle.js"',
    ".combined-stacks-section",
    ".flame-segment",
    'id="scalene-app"',
    'id="scalene-footer"',
    "load(profile)",
  ]) {
    if (!text.includes(needle)) out.push(`template is missing ${JSON.stringify(needle)}`);
  }
  // Every other use of `profile` would inline unescaped JSON.
  const uses = text.match(/\{\{(?:(?!\}\}).)*\bprofile\b(?:(?!\}\}).)*\}\}/g) ?? [];
  if (uses.length !== 1) out.push(`template inlines profile ${uses.length} times (expected exactly once, escaped)`);
  if (/experimental/i.test(text)) out.push('template contains "experimental"');
  if (text.includes("bg-warning text-dark")) out.push('template contains "bg-warning text-dark"');
  return out;
}
